const sampleNotes=Array.from({length:17},(_,i)=>36+i*3);
const sampleName=n=>['C','Cs','D','Ds','E','F','Fs','G','Gs','A','As','B'][n%12]+(Math.floor(n/12)-1);
export class Piano {
 constructor(){this.context=new (window.AudioContext||window.webkitAudioContext)();this.buffers=new Map;this.active=new Set;this.master=this.context.createGain();this.master.gain.value=.68;const compressor=this.context.createDynamicsCompressor();compressor.threshold.value=-14;compressor.ratio.value=3;this.master.connect(compressor).connect(this.context.destination);this.ready=null;}
 async load(){await this.context.resume();if(!this.ready)this.ready=Promise.all(sampleNotes.map(async note=>{const r=await fetch('./audio/'+sampleName(note)+'.mp3');if(!r.ok)throw Error('Piano sample unavailable');const buffer=await this.context.decodeAudioData(await r.arrayBuffer());this.buffers.set(note,buffer);})).catch(e=>{this.ready=null;throw e;});return this.ready;}
 note(note,when,duration,velocity){const ctx=this.context;const key=sampleNotes.reduce((a,b)=>Math.abs(b-note)<Math.abs(a-note)?b:a);const source=ctx.createBufferSource(),gain=ctx.createGain(),filter=ctx.createBiquadFilter();source.buffer=this.buffers.get(key);source.playbackRate.value=2**((note-key)/12);filter.type='lowpass';filter.frequency.value=2800+velocity*8500;const amp=.5*velocity**1.5;const release=.22+velocity*.12;gain.gain.setValueAtTime(0,when);gain.gain.linearRampToValueAtTime(amp,when+.005);gain.gain.setValueAtTime(amp,when+Math.max(.006,duration));gain.gain.exponentialRampToValueAtTime(.0001,when+duration+release);source.connect(filter).connect(gain).connect(this.master);source.start(when);source.stop(when+duration+release+.02);this.active.add(source);source.onended=()=>{this.active.delete(source);source.disconnect();filter.disconnect();gain.disconnect();};}
 stop(){this.active.forEach(s=>{try{s.stop();}catch{}});this.active.clear();}
}
